M ID(){M r;for(int i=0;i<16;i++)r.m[i]=i%5==0?1:0;return r;}
M PR(F fov,F asp,F n,F f){M r=ID();F t=tan(fov*0.5f),a=1.0f/t;r.m[0]=a/asp;r.m[5]=a;r.m[10]=-(f+n)/(f-n);r.m[11]=-1;r.m[14]=-(2*f*n)/(f-n);r.m[15]=0;return r;}
M LK(V e,V c,V u){V f={c.x-e.x,c.y-e.y,c.z-e.z};F l=sqrt(f.x*f.x+f.y*f.y+f.z*f.z);f.x/=l;f.y/=l;f.z/=l;V s={f.y*u.z-f.z*u.y,f.z*u.x-f.x*u.z,f.x*u.y-f.y*u.x};l=sqrt(s.x*s.x+s.y*s.y+s.z*s.z);s.x/=l;s.y/=l;s.z/=l;V uu={s.y*f.z-s.z*f.y,s.z*f.x-s.x*f.z,s.x*f.y-s.y*f.x};M r=ID();r.m[0]=s.x;r.m[4]=s.y;r.m[8]=s.z;r.m[1]=uu.x;r.m[5]=uu.y;r.m[9]=uu.z;r.m[2]=-f.x;r.m[6]=-f.y;r.m[10]=-f.z;r.m[12]=-(s.x*e.x+s.y*e.y+s.z*e.z);r.m[13]=-(uu.x*e.x+uu.y*e.y+uu.z*e.z);r.m[14]=f.x*e.x+f.y*e.y+f.z*e.z;return r;}
void LV(U*d,L*lp,V**ov,I*on){nbv=lp[2].l/12;vt=malloc(nbv*sizeof(V));memcpy(vt,d+lp[2].o,lp[2].l);*ov=vt;*on=nbv;printf("Verts: %d\n",nbv);}
