void BS(const char*p){I sz;U*d=LB(p,&sz);if(!d||sz<8||memcmp(d,"IBSP",4)||((I*)d)[1]!=38){printf("Bad BSP\n");exit(1);}L*lp=(L*)(d+8);V*v;E*ed;FE*fe;I ne,tmp;LV(d,lp,&v,&tmp);LF(d,lp,&fc,&nfc,&ed,&fe);LT(d,lp,&ti,&ne);LL(d,lp,&lmd);I nt=0;for(I i=0;i<nfc;i++)if(fc[i].ne>=3)nt+=(fc[i].ne-2)*3;vd=malloc(nt*10*sizeof(F));printf("Alloc %d verts\n",nt);I vi=0;for(I i=0;i<nfc;i++){FC*f=&fc[i];if(f->ne<3)continue;for(J j=1;j<f->ne-1;j++){for(J k=0;k<3;k++){J idx=k==0?0:(k==1?j:j+1),ei=fe[f->fe+idx].e,ev=ei<0?1:0;V*vv=&v[ed[abs(ei)].v[ev]];vd[vi++]=vv->x;vd[vi++]=vv->y;vd[vi++]=vv->z;TI*t=&ti[f->ti];F u=(vv->x*t->u[0]+vv->y*t->u[1]+vv->z*t->u[2]+t->ou)/64.0f,w=(vv->x*t->v[0]+vv->y*t->v[1]+vv->z*t->v[2]+t->ov)/64.0f;vd[vi++]=u;vd[vi++]=w;vd[vi++]=0.5f;vd[vi++]=0.5f;vd[vi++]=0;vd[vi++]=0;vd[vi++]=1;}}}nv=vi/10;free(d);free(ed);free(fe);printf("Built %d tris (%d verts)\n",nv/3,nv);}
void DR(){glGenVertexArrays(1,&vao);glGenBuffers(1,&vbo);glBindVertexArray(vao);glBindBuffer(GL_ARRAY_BUFFER,vbo);glBufferData(GL_ARRAY_BUFFER,nv*10*sizeof(F),vd,GL_STATIC_DRAW);glEnableVertexAttribArray(0);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,10*sizeof(F),(void*)0);glEnableVertexAttribArray(1);glVertexAttribPointer(1,2,GL_FLOAT,GL_FALSE,10*sizeof(F),(void*)(3*sizeof(F)));glEnableVertexAttribArray(2);glVertexAttribPointer(2,2,GL_FLOAT,GL_FALSE,10*sizeof(F),(void*)(5*sizeof(F)));glEnableVertexAttribArray(3);glVertexAttribPointer(3,3,GL_FLOAT,GL_FALSE,10*sizeof(F),(void*)(7*sizeof(F)));}
