void UP(F*k){F sp=sin(pi),cp=cos(pi),sy=sin(ya),cy=cos(ya);V f={cp*cy,cp*sy,sp},r={-sy,cy,0},u={-sp*cy,-sp*sy,cp};F ms=k[SDL_SCANCODE_LSHIFT]?10:5;if(k[SDL_SCANCODE_W]){cm.x+=f.x*ms;cm.y+=f.y*ms;cm.z+=f.z*ms;}if(k[SDL_SCANCODE_S]){cm.x-=f.x*ms;cm.y-=f.y*ms;cm.z-=f.z*ms;}if(k[SDL_SCANCODE_A]){cm.x+=r.x*ms;cm.y+=r.y*ms;}if(k[SDL_SCANCODE_D]){cm.x-=r.x*ms;cm.y-=r.y*ms;}if(k[SDL_SCANCODE_SPACE])cm.z+=ms;if(k[SDL_SCANCODE_LCTRL])cm.z-=ms;}
void RN(F*k){UP(k);V t={cm.x+cos(pi)*cos(ya),cm.y+cos(pi)*sin(ya),cm.z+sin(pi)};M mo=ID(),vi=LK(cm,t,(V){0,0,1}),pj=PR(1.2f,(F)W/H,1.0f,4000.0f);glUniformMatrix4fv(glGetUniformLocation(prg,"m"),1,GL_FALSE,mo.m);glUniformMatrix4fv(glGetUniformLocation(prg,"v"),1,GL_FALSE,vi.m);glUniformMatrix4fv(glGetUniformLocation(prg,"j"),1,GL_FALSE,pj.m);glUniform3f(glGetUniformLocation(prg,"a"),cm.x,cm.y,cm.z);glUniform1f(glGetUniformLocation(prg,"g"),0.0005f);glClearColor(0.5f,0.6f,0.7f,1.0f);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);glBindVertexArray(vao);glDrawArrays(GL_TRIANGLES,0,nv);SDL_GL_SwapWindow(win);}
int main(int argc,char**argv){cm=(V){0,0,50};printf("Starting...\n");IN();printf("SDL OK\n");SH();printf("Shaders OK\n");BS(argc>1?argv[1]:"baseq2/maps/sample.bsp");printf("BSP OK\n");DR();I run=1,fc=0;F*k=calloc(512,sizeof(F));SDL_Event e;SDL_SetRelativeMouseMode(1);while(run){while(SDL_PollEvent(&e)){if(e.type==SDL_QUIT||(e.type==SDL_KEYDOWN&&e.key.keysym.sym==SDLK_ESCAPE))run=0;if(e.type==SDL_KEYDOWN)k[e.key.keysym.scancode]=1;if(e.type==SDL_KEYUP)k[e.key.keysym.scancode]=0;if(e.type==SDL_MOUSEMOTION){ya-=e.motion.xrel*0.002f;pi+=e.motion.yrel*0.002f;if(pi>1.5f)pi=1.5f;if(pi<-1.5f)pi=-1.5f;}}RN(k);if(++fc==60){SS("phase2.ppm");run=0;}SDL_Delay(16);}free(k);free(vd);glDeleteVertexArrays(1,&vao);glDeleteBuffers(1,&vbo);glDeleteProgram(prg);SDL_GL_DeleteContext(ctx);SDL_DestroyWindow(win);SDL_Quit();return 0;}
